@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class StorageRenderWorldChecks {
 private static volatile boolean enabled=true,captured;private static NativeStorageModel.Bake bake;private static int generation,stage,ticks,wait,frames,checks;private static String capture;
 private static void need(boolean yes,String why){checks++;if(!yes)throw new IllegalStateException("Storage render client stage="+stage+": "+why);}
 private static final class Gate extends BakedModelWrapper<BakedModel>{Gate(BakedModel source){super(source);}@Override public List<net.minecraft.client.renderer.block.model.BakedQuad> getQuads(BlockState s,Direction side,RandomSource r,ModelData d,RenderType layer){return enabled?super.getQuads(s,side,r,d,layer):List.of();}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public static final class Binding {
  @SubscribeEvent public static void screens(RegisterMenuScreensEvent event){if(StorageRenderWorldFixture.enabled())NativeStorageScreen.register(event,StorageRenderWorldFixture.MENU);}
  @SubscribeEvent(priority=EventPriority.LOWEST)public static void models(ModelEvent.ModifyBakingResult event){if(!StorageRenderWorldFixture.enabled())return;var materials=new HashMap<Integer,ProgrammableModel.MaterialSnapshot>();for(var choice:ModernFinishCatalog.choicesForBake()){var e=choice.entry();materials.put(choice.choice(),new ProgrammableModel.MaterialSnapshot(event.getTextureGetter().apply(new Material(TextureAtlas.LOCATION_BLOCKS,ResourceLocation.parse(e.texture()))),e.u(),e.v()));}bake=new NativeStorageModel.Bake(materials,event.getTextureGetter());for(var state:StorageRenderWorldFixture.BLOCK.getStateDefinition().getPossibleStates()){var key=BlockModelShaper.stateToModelLocation(state);var original=event.getModels().get(key);need(original!=null,"authored private model present");event.getModels().put(key,new Gate(bake.wrap(original)));}var itemKey=new ModelResourceLocation(ResourceLocation.parse("vandorlabs:storage_render_fixture"),"inventory");var item=event.getModels().get(itemKey);need(item!=null,"authored private item model present");StorageItemRenderChecks.bind(item,bake);event.getModels().put(itemKey,new NativeStorageItemModel(item,bake));generation++;}
 }
 private static NativeStorageEntity at(Minecraft mc,BlockPos pos){return mc.level.getBlockEntity(pos) instanceof NativeStorageEntity owner?owner:null;}
 private static void shot(String name){capture=name;captured=false;frames=0;}
 private static void mode(int operation){PacketDistributor.sendToServer(new StorageRenderWorldFixture.Mode(operation));wait=ticks;}
 private static boolean actor(Minecraft mc,GameType mode,double x,double z,boolean tool){return mc.gameMode.getPlayerMode()==mode&&mc.player.getInventory().selected==0&&mc.player.getOffhandItem().isEmpty()&&(tool?mc.player.getMainHandItem().is(VandorLabsBootstrap.CONFIGURIZER.get()):mc.player.getMainHandItem().isEmpty())&&Math.abs(mc.player.getX()-x)<.04&&Math.abs(mc.player.getZ()-z)<.04;}
 private static void projections(Minecraft mc){int[] choices=StorageRenderWorldFixture.choices();for(int i=0;i<choices.length;i++){var owner=at(mc,StorageRenderWorldFixture.cell(i));need(owner!=null&&owner.visual().settings().housing().mainTexture==choices[i],"all14 installed public choices");need(!owner.getUpdateTag(mc.level.registryAccess()).contains("Items"),"physical slots absent from public projection");var state=owner.getBlockState();var model=mc.getBlockRenderer().getBlockModel(state);need(model instanceof Gate&&!model.useAmbientOcclusion(),"actual chunk model wrapper/noAO");for(var side:Direction.values()){var quads=model.getQuads(state,side,RandomSource.create(0),owner.getModelData(),null);need(quads.size()==1&&!quads.getFirst().isShade(),"one Source face with no diffuse shade");}need(model.getQuads(state,null,RandomSource.create(0),owner.getModelData(),null).isEmpty(),"sided chunk emission only");}
  for(var pos:new BlockPos[]{StorageRenderWorldFixture.STONE,StorageRenderWorldFixture.SLAB,StorageRenderWorldFixture.GLASS}){boolean expected=!pos.equals(StorageRenderWorldFixture.STONE);need(Block.shouldRenderFace(mc.level.getBlockState(pos),mc.level,pos,Direction.EAST,pos.east())==expected,"actual vanilla opaque/partial/transparent side culling "+pos);need(!Block.shouldRenderFace(mc.level.getBlockState(pos),mc.level,pos,Direction.DOWN,pos.below()),"floor side culled");}
  var on=at(mc,StorageRenderWorldFixture.GUI);var off=at(mc,StorageRenderWorldFixture.INHERIT);var model=mc.getBlockRenderer().getBlockModel(on.getBlockState());String explicit=model.getQuads(on.getBlockState(),Direction.UP,RandomSource.create(0),on.getModelData(),null).getFirst().getSprite().contents().name().toString();String inherited=model.getQuads(off.getBlockState(),Direction.UP,RandomSource.create(0),off.getModelData(),null).getFirst().getSprite().contents().name().toString();need(explicit.endsWith("cabinet_front")&&inherited.endsWith("cabinet_top"),"explicit Storage face uses front while disabled override inherits top: "+explicit+" / "+inherited);
  var data=on.getModelData();need(model.getModelData(null,on.getBlockPos(),on.getBlockState(),data)==data,"chunk model preparation reads no world");var future=java.util.concurrent.CompletableFuture.runAsync(()->{for(int n=0;n<1000;n++)model.getQuads(on.getBlockState(),Direction.NORTH,null,data,null);});future.join();var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);for(int n=0;n<12000;n++)model.getQuads(on.getBlockState(),Direction.NORTH,null,data,null);long before=meter.getThreadAllocatedBytes(Thread.currentThread().threadId());for(int n=0;n<10000;n++)model.getQuads(on.getBlockState(),Direction.NORTH,null,data,null);long allocated=meter.getThreadAllocatedBytes(Thread.currentThread().threadId())-before;need(allocated<=1024&&bake.cacheBytes()<=NativeStorageModel.Bake.MESH_BUDGET+8192,"actual chunk warm allocation="+allocated+" cache="+bake.cacheBytes());CubeReferenceChecks.run(mc);System.out.println("[vandorlabs][storage-render-world] model PASS generation="+generation+" checks="+checks+" warm10000="+allocated+" cache="+bake.cacheBytes());
 }
 private static void click(NativeStorageScreen screen,int id,int button){var c=screen.controls().stream().filter(v->v.id==id).findFirst().orElseThrow();need(screen.mouseClicked(c.x+c.width/2D,c.y+7,button),"actual control "+id);}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!StorageRenderWorldFixture.enabled()||stage==99)return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen s){s.onClose();return;}if(stage==90&&mc.level==null){System.out.println("[vandorlabs][storage-render-world] client PASS checks="+checks+" chunks/14sets/override/culling/worker/warm/picker/reload");stage=99;mc.stop();return;}if(mc.level==null||mc.player==null||mc.gameMode==null)return;need(++ticks<1800,"timeout mode="+mc.gameMode.getPlayerMode()+" slot="+mc.player.getInventory().selected+" held="+mc.player.getMainHandItem()+" pos="+mc.player.position()+" screen="+mc.screen);
  switch(stage){case 0->{if(ticks<120||!actor(mc,GameType.CREATIVE,11.5,-15,false)||at(mc,StorageRenderWorldFixture.GLASS)==null)return;projections(mc);mc.options.hideGui=true;mc.options.fov().set(70);mc.options.bobView().set(false);mc.options.cloudStatus().set(CloudStatus.OFF);shot("storage-world-positive.png");stage=1;}case 1->{if(!captured)return;enabled=false;mc.levelRenderer.allChanged();shot("storage-world-disabled.png");stage=2;}case 2->{if(!captured)return;enabled=true;mc.reloadResourcePacks();wait=ticks;stage=3;}case 3->{if(mc.getOverlay()!=null||ticks<wait+100)return;need(generation>=2,"new bake on actual resource reload");projections(mc);shot("storage-world-reloaded.png");stage=4;}case 4->{if(!captured)return;mc.options.hideGui=false;mode(0);stage=5;}case 5->{if(!actor(mc,GameType.SURVIVAL,-8.5,-3,true)||ticks<wait+20)return;mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(-8.5,96.5,0),Direction.NORTH,StorageRenderWorldFixture.GUI,false));stage=6;}case 6->{if(!(mc.screen instanceof NativeStorageScreen screen))return;click(screen,ProgrammableBlockDialog.TEXTURE_LAYOUT,0);click(screen,ProgrammableBlockDialog.TEXTURE_LAYOUT,0);need(screen.editingState().layout==2,"actual two forward layout controls");var picker=screen.activePicker();var panel=screen.panel();picker.searchField().setValue(ModernFinishCatalog.option(296).label());int index=picker.rows().indexOf(296);need(index>=0,"Source Storage material exists in shared picker");while(index-picker.scroll()>=picker.visible())screen.mouseScrolled(panel.listX+10,picker.top()+10,0,-1);need(screen.mouseClicked(panel.listX+12,picker.top()+(index-picker.scroll())*22+10,0),"actual material row click");stage=7;}case 7->{if(at(mc,StorageRenderWorldFixture.GUI).settings().housing().mainTexture!=296)return;mc.player.closeContainer();mode(1);stage=8;}case 8->{if(!actor(mc,GameType.CREATIVE,11.5,-15,false)||!mc.level.getBlockState(StorageRenderWorldFixture.ACK.east()).is(Blocks.STONE)||ticks<wait+60)return;mc.options.hideGui=true;shot("storage-world-edited.png");stage=9;}case 9->{if(!captured)return;mode(2);stage=10;}case 10->{if(!mc.level.getBlockState(StorageRenderWorldFixture.ACK.east(2)).is(Blocks.STONE))return;mc.level.disconnect();mc.disconnect();stage=90;}}
 }
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!StorageRenderWorldFixture.enabled()||capture==null||++frames<60)return;var mc=Minecraft.getInstance();String name=capture;capture=null;Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),message->captured=true);}
}
